The following statements are equivalent:

\begin{enumerate}
    \item $(X,P)$ is irreducible;

    \item the accessibility preorder $\preceq$ satisfies
    \[
    x\preceq y
    \qquad \text{for all } x,y\in X;
    \]

    \item $\tau_P$ is the trivial topology on $X$, that is,
    \[
    \tau_P=\{\varnothing,X\}.
    \]
\end{enumerate}

For each $x\in X$, the set $P_P(x)$ is the smallest open set in $\tau_P$ containing $x$. That is:

\begin{enumerate}
    \item $P_P(x)\in\tau_P$;

    \item $x\in P_P(x)$;

    \item if $U\in\tau_P$ and $x\in U$, then
    \[
    P_P(x)\subseteq U.
    \]
\end{enumerate}

\label{T:hitting}
For a subset $U\subseteq X$, define the first hitting time of $U$ by
\[
\tau_U:=\inf\{n\geq 0 : X_n\in U\}.
\]
Then the following are equivalent:

\begin{enumerate}
    \item $U\in\tau_P$;

    \item
    $ \displaystyle{
    \mathbb P_y(\tau_U<\infty)=0,
    \qquad \text{for every } y\in X\setminus U.
    }$
\end{enumerate}
